# Lazy-load nvm in interactive shells; default Node comes from ~/.zprofile PATH.
export NVM_DIR="$HOME/.nvm"
_load_nvm() {
  unset -f nvm _load_nvm
  [ -s "$NVM_DIR/nvm.sh" ] && \. "$NVM_DIR/nvm.sh"
  [ -s "$NVM_DIR/bash_completion" ] && \. "$NVM_DIR/bash_completion"
}
nvm() {
  _load_nvm
  nvm "$@"
}

// Cursor/VS Code shell env resolution timeout (seconds); raise if shell startup is slow.
"application.shellEnvironmentResolutionTimeout": 60,

